  /** The create/edit dialog: scoped by its title field, since toasts and
   * the account menu also render as dialogs. */
  private createDialog(): Locator {
    return this.page.getByRole("dialog").filter({ has: this.page.getByPlaceholder("Title") });
  }

  /** The draft modal (create, copy, edit or move): headed "…draft…". */
  private draftDialogTitle(): Locator {
    return this.createDialog().getByRole("heading").first();
  }

  /** One draft block, located by the name it shows. */
  private draftBlock(name: string): Locator {
    return this.page
      .locator("[data-draft-block]")
      .filter({ has: this.page.locator("p[data-draft-name]", { hasText: name }) })
      .first();
  }

  /** One inline property slot inside a named draft row. */
  private draftProperty(name: string, property: string): Locator {
    return this.draftBlock(name).locator(`[data-draft-property="${property}"]`);
  }

  /** The rendered text of one inline property slot. */
  private async draftPropertyText(name: string, property: string): Promise<string> {
    const slot = this.draftProperty(name, property);
    await slot.waitFor({ timeout: 60_000 });
    return ((await slot.innerText()) ?? "").replace(/\s+/g, " ").trim();
  }

  /** The trigger opening one inline property picker. */
  private draftPropertyTrigger(name: string, property: string): Locator {
    return this.draftProperty(name, property).getByRole("button").first();
  }

  /**
   * The rendered text of one project-feature slot (estimate, cycle or
   * modules): blank when the draft's project does not offer the
   * control, so gated rows read empty instead of throwing.
   */
  private async draftOptionalPropertyText(name: string, property: string): Promise<string> {
    const block = this.draftBlock(name);
    await block.waitFor({ timeout: 60_000 });
    const slot = this.draftProperty(name, property);
    if ((await slot.count()) === 0) return "";
    return WebNewDriver.cleanDraftText(await slot.innerText().catch(() => null));
  }

  /**
   * The trigger of one project-feature slot, failing fast with the
   * missing control named when the project does not offer it.
   */
  private async draftOptionalPropertyTrigger(name: string, property: string): Promise<Locator> {
    const block = this.draftBlock(name);
    await block.waitFor({ timeout: 60_000 });
    if ((await this.draftProperty(name, property).count()) === 0) {
      throw new Error(`[parity] no ${property} control on draft ${JSON.stringify(name)}.`);
    }
    return this.draftPropertyTrigger(name, property);
  }

  /** Open a draft's ellipsis menu and choose one entry. */
  private async openDraftMenu(name: string, entry: string): Promise<void> {
    const block = this.draftBlock(name);
    await block.waitFor({ timeout: 60_000 });
    await block.getByRole("button", { name: `Actions for ${name}`, exact: true }).click();
    await this.page.getByRole("menuitem", { name: entry, exact: true }).first().click();
  }

  /** The project chip inside the open dialog (the first chip in the form). */
  private modalProjectChip(): Locator {
    return this.createDialog().locator("form").getByRole("button").first();
  }

  async hoverCardRead(_issueName: string): Promise<{ text: string; priorityIcon: string; dateColor: string }> {
    // The card names the record in its key, title and state, so one open
    // card is the read: no per-name scoping that a redesign could break.
    const card = this.page.getByTestId("work-item-preview").first();
    if ((await card.count()) === 0) return { text: "", priorityIcon: "", dateColor: "" };
    const waited = await card
      .waitFor({ state: "visible", timeout: 15_000 })
      .then(() => true)
      .catch(() => false);
    if (!waited) return { text: "", priorityIcon: "", dateColor: "" };
    return card.evaluate((element: HTMLElement) => {
      const text = (element.textContent ?? "").replace(/\s+/g, " ").trim();
      const glyph = element.querySelector('[data-testid="preview-card-priority"] svg');
      const priorityIcon = (glyph?.getAttribute("class") ?? "")
        .split(/\s+/)
        .filter((name) => name.startsWith("lucide-") && name !== "lucide")
        .join(" ");
      const dates = element.querySelector('[data-testid="preview-card-dates"]');
      const dateColor = dates === null ? "" : getComputedStyle(dates).color;
      return { text, priorityIcon, dateColor };
    });
  }

