  private async routeGptStub(): Promise<void> {
    // The issue modal posts the project task endpoint; nothing else on
    // the page shares its trailing segments, so the glob stays exact.
    await this.page.unroute("**/api/workspaces/*/projects/*/ai-assistant/");
    await this.page.route("**/api/workspaces/*/projects/*/ai-assistant/", async (route) => {
      const request = route.request();
      if (request.method() !== "POST") {
        await route.fallback();
        return;
      }
      const body = (request.postDataJSON() ?? {}) as { prompt?: unknown; task?: unknown };
      this.assistantGptSeen.push({
        prompt: typeof body["prompt"] === "string" ? body["prompt"] : "",
        task: typeof body["task"] === "string" ? body["task"] : "",
      });
      const failure = this.assistantGptFailure;
      if (failure !== null) {
        await route.fulfill({
          status: failure.status,
          contentType: "application/json",
          body: JSON.stringify(failure.body),
        });
        return;
      }
      await route.fulfill({
        status: 200,
        contentType: "application/json",
        // The project endpoint also echoes the row it ran for. The client
        // validates that envelope, so the canned answer must carry the
        // same detail objects a live response does.
        body: JSON.stringify({
          ...this.assistantGptAnswerStub,
          project_detail: {
            id: "00000000-0000-4000-8000-000000000001",
            identifier: "PAR",
            name: "Parity project",
            cover_image: null,
            cover_image_url: null,
            logo_props: {},
            description: "",
            is_default: false,
          },
          workspace_detail: {
            name: "Parity workspace",
            slug: "parity-workspace",
            id: "00000000-0000-4000-8000-000000000002",
            logo_url: null,
          },
        }),
      });
    });
  }
