    const dialog = this.cycleArchiveDialog();
    await dialog.getByRole("button", { name: "Cancel", exact: true }).click({ timeout: WebNewDriver.WAIT_MS });
    await dialog.waitFor({ state: "detached", timeout: WebNewDriver.WAIT_MS });
