  async draftsDelayList(ms: number): Promise<void> {
    // Hold the drafts-list answers so the skeleton stays up long enough
    // to observe; writes pass through untouched. A URL predicate (not a
    // glob) routes the request, mirroring the oracle driver.
    const matches = (url: URL): boolean =>
      url.pathname.includes("/api/workspaces/") && url.pathname.includes("/draft-issues/");
    const hold = async (route: Route): Promise<void> => {
      if (route.request().method() !== "GET") {
        await route.continue();
        return;
      }
      await new Promise((resolve) => setTimeout(resolve, ms));
      await route.continue();
    };
    await this.page.route(matches, hold);
  }
  async draftsSkeletonVisible(): Promise<boolean> {
    const region = this.draftsRegion();
    if (
      await region
        .getByTestId("drafts-loading")
        .isVisible()
        .catch(() => false)
    )
      return true;
    return region
      .getByTestId("drafts-load-more-loading")
      .isVisible()
      .catch(() => false);
  }
  async draftsLoadMoreVisible(): Promise<boolean> {
    return (
      (await this.draftsRegion()
        .getByRole("button", { name: /Load more/ })
        .count()) > 0
    );
  }
  async draftsLoadMore(): Promise<void> {
    const before = await this.draftBlockCount();
    await this.draftsRegion()
      .getByRole("button", { name: /Load more/ })
      .first()
      .click({ timeout: WebNewDriver.WAIT_MS });
    await expect.poll(() => this.draftBlockCount(), { timeout: WebNewDriver.WAIT_MS }).toBeGreaterThan(before);
  }
  async draftsListFetchCountOnRefocus(): Promise<number> {
    // Count drafts-list reads across a blur/focus cycle: the screen
    // fetches on mount only, never on refocus.
    let calls = 0;
    const matches = (url: URL): boolean =>
      url.pathname.includes("/api/workspaces/") && url.pathname.includes("/draft-issues/");
    const counter = async (route: Route): Promise<void> => {
      if (route.request().method() === "GET") calls += 1;
      await route.continue();
    };
    await this.page.route(matches, counter);
    try {
      await this.page.evaluate(() => {
        window.dispatchEvent(new Event("blur"));
        document.dispatchEvent(new Event("visibilitychange"));
        window.dispatchEvent(new Event("focus"));
        document.dispatchEvent(new Event("visibilitychange"));
      });
      await this.page.waitForTimeout(3000);
      return calls;
    } finally {
      await this.page.unroute(matches, counter).catch(() => undefined);
    }
  }
  async draftsMainCheckboxCount(): Promise<number> {
    const region = this.draftsRegion();
    if ((await region.count()) === 0) return 0;
    return region.getByRole("checkbox").count();
  }

  // Modules dialogs and delete confirmation (NEWFRONT-798, MOD-003/009/
  // 022–025). The new app renders the save form under one heading
  // ("Create module" / "Update module") with the project picker only in
  // creation, the title/description fields by name, and the four inline
  // controls by testid; the delete confirmation names the module in its
  // body. The pinned keyboard sequence carries the date control third
  // (NEWFRONT-330), so the tab-order reader walks the same eight stops.

  /** The open save dialog (create or update), scoped by its title field. */
  private moduleSaveDialog(): Locator {
    return this.page
      .getByRole("dialog")
      .filter({ has: this.page.locator('input[name="name"]') })
      .first();
  }

  /** The open delete confirmation. */
  private moduleDeleteDialogRoot(): Locator {
    return this.page
      .getByRole("dialog")
      .filter({ has: this.page.getByTestId("module-delete-body") })
      .first();
  }

  /** Wait for the save dialog's content; the root can stay zero-sized. */
  private async moduleAwaitSaveDialog(): Promise<Locator> {
    const dialog = this.moduleSaveDialog();
    await dialog.locator('input[name="name"]').waitFor({ timeout: WebNewDriver.WAIT_MS });
    return dialog;
  }

  private moduleInlineControl(testId: string): Locator {
    return this.moduleSaveDialog().getByTestId(testId).first();
  }

  /**
   * A picker control's readable text, decoration dropped: the project mark
   * and avatar glyphs are `aria-hidden`, so they must not leak into a name
   * asserted by a scenario.
   */
  private async modulesInlineControlText(testId: string): Promise<string> {
    const texts = await this.moduleInlineControl(testId).evaluateAll(moduleVisibleTexts);
    return texts.join(" ").trim();
  }

  /** Labels of the selected options in the open popup (none when nothing is set). */
  private async modulesSelectedOptionLabels(): Promise<string[]> {
    const selected = this.page.locator(MODULE_SELECTED_OPTION_SELECTOR);
    await this.page.getByRole("option").first().waitFor({ timeout: WebNewDriver.WAIT_MS });
    return selected.evaluateAll(moduleVisibleTexts);
  }

  /** Close the open option popup and wait for it to detach. */
  private async modulesDismissOptionPopup(): Promise<void> {
    await this.page.keyboard.press("Escape");
    await this.page
      .getByRole("option")
      .first()
      .waitFor({ state: "detached", timeout: 5_000 })
      .catch(() => undefined);
  }

