  private profileExportStall: {
    pattern: string;
    handler: (route: Route) => Promise<void>;
    mode: "pass" | "stall";
    gates: Array<() => void>;
  } | null = null;

  async profileActivityStallExport(): Promise<void> {
    if (this.profileExportStall !== null) {
      this.profileExportStall.mode = "stall";
      return;
    }
    const stall: NonNullable<WebNewDriver["profileExportStall"]> = {
      pattern: "**/api/workspaces/*/user-activity/*/export/**",
      handler: async (): Promise<void> => undefined,
      mode: "stall",
      gates: [],
    };
    // The handler stays installed for the page's life: stalled POSTs wait
    // on a gate, everything else falls through. Releasing resolves the
    // gates instead of unrouting (unroute drops the held route, so a
    // later continue() throws "already handled").
    stall.handler = async (route: Route): Promise<void> => {
      if (route.request().method() === "POST" && stall.mode === "stall") {
        await new Promise<void>((resolve) => {
          stall.gates.push(resolve);
        });
      }
      await route.fallback();
    };
    this.profileExportStall = stall;
    await this.page.route(stall.pattern, stall.handler);
  }

  async profileActivityReleaseExport(): Promise<void> {
    const stall = this.profileExportStall;
    if (stall === null) return;
    const gates = stall.gates;
    stall.gates = [];
    stall.mode = "pass";
    gates.forEach((release) => release());
  }

  async profileActivityDownload(): Promise<{ file: LocalFileDownload; requestBody: { date: string } }> {
    const request = this.page.waitForRequest(
      (candidate) => candidate.method() === "POST" && /\/user-activity\/[^/]+\/export\//.test(candidate.url()),
      { timeout: WebNewDriver.WAIT_MS }
    );
    const [download] = await Promise.all([
      this.page.waitForEvent("download", { timeout: 60_000 }),
      this.page.getByTestId("profile-activity-download").click({ timeout: WebNewDriver.WAIT_MS }),
    ]);
    const posted = await request;
    const body = posted.postDataJSON() as { date?: string } | null;
    const stream = await download.createReadStream();
    if (!stream) throw new Error("[parity] profile activity download produced no bytes.");
    const chunks: Buffer[] = [];
    for await (const chunk of stream) chunks.push(Buffer.from(chunk));
    return {
      file: { fileName: download.suggestedFilename(), content: Buffer.concat(chunks).toString("utf8") },
      requestBody: { date: body?.date ?? "" },
    };
  }

  // --- Reactions oracle (NEWFRONT-116, CMT-022/023/024). Throwing stubs per
  // --- the shared driver contract; the new app implements them later.
  async reactionsIssueChipTooltipText(emoji: string, expectedName: string): Promise<string> {
    await this.issueReactionRow()
      .locator("button:not([aria-haspopup])", { hasText: emoji })
      .first()
      .hover({ timeout: WebNewDriver.WAIT_MS });
    await this.page.waitForFunction((name) => document.body.innerText.includes(name), expectedName, {
      timeout: WebNewDriver.WAIT_MS,
    });
    return this.page.evaluate((name) => {
      const candidates = Array.from(document.querySelectorAll("body *")).filter((el) =>
        (el as HTMLElement).innerText?.includes(name)
      );
      candidates.sort((a, b) => a.innerHTML.length - b.innerHTML.length);
      return ((candidates[0] as HTMLElement | undefined)?.innerText ?? "").slice(0, 200);
    }, expectedName);
  }
