    const total = await boxes.count();
    const labels: string[] = [];
    for (let i = 0; i < total; i++) {
      const label = ((await boxes.nth(i).getAttribute("aria-label")) ?? "").trim();
      if (label !== "") labels.push(label);
    }
    return labels;
