    await this.wsSettingsOpenSection(workspaceSlug, "webhooks", cookies);
    await this.page
      .getByRole("button", { name: "Add webhook", exact: true })
      .first()
      .click({ timeout: WebNewDriver.WAIT_MS });
    await this.wsSettingsAwaitDialog();
