    // dialog would still close on Escape.
    if (!(await this.wsSettingsUpgradeModalVisible())) return;
    await this.page.keyboard.press("Escape");
    await expect
      .poll(() => this.wsSettingsUpgradeModalVisible(), { timeout: 15_000 })
      .toBe(false)
      .catch(() => undefined);
