    await this.page.getByTestId("general-emblem-open").click({ timeout: WebNewDriver.WAIT_MS });
    await expect.poll(() => this.settingsGeneralEmblemPickerVisible(), { timeout: WebNewDriver.WAIT_MS }).toBe(true);
